.15s,transform .15s}.pd-v2 .pd-pay:not(:disabled):hover{background:#ffad69;transform:translateY(-1px)}.pd-v2 .pd-pay:disabled{cursor:not-allowed;opacity:.68}.pd-v2 .pd-note{font-size:11px;line-height:1.55;color:var(--muted);margin:0}.pd-v2 .pd-note a{color:inherit;text-decoration:underline}.pd-v2 .pd-status{font-size:12px;line-height:1.4;color:var(--muted)}.pd-v2 .pd-status:empty{display:none}.pd-v2 .pd-bottom{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding-top:10px}.pd-v2 .pd-chip{padding:17px 20px;border-radius:20px;background:#fff;display:flex;gap:10px;align-items:center;font-size:12px;line-height:1.4}.pd-v2 .pd-chip svg{flex:none;width:24px;height:24px;stroke:#ab581c}.pd-v2 .pd-chip b{display:block;font-size:13px}.pd-v2 .pd-chip small{color:var(--muted);font-size:11px}.pd-v2 :focus-visible{outline:2px solid #e58e47;outline-offset:3px}@media(max-width:760px){.pd-v2{border-radius:25px;padding:8px;margin:12px auto}.pd-v2 .pd-grid{grid-template-columns:1fr}.pd-v2 .pd-story,.pd-v2 .pd-checkout{border-radius:20px}.pd-v2 .pd-head{font-size:49px}.pd-v2 .pd-art{max-width:400px;align-self:center;margin:10px 0}.pd-v2 .pd-bottom{grid-template-columns:1fr}.pd-v2 .pd-chip{padding:13px 16px}}@media(max-width:360px){.pd-v2 .pd-option{padding:13px 9px;gap:6px}.pd-v2 .pd-amount{font-size:20px}.pd-v2 .pd-checkout{padding:16px}.pd-v2 .pd-head{font-size:39px}}@media(prefers-reduced-motion:reduce){.pd-v2 *{transition:none!important}}
