<script data-category="functional">
(()=>{const root=document.getElementById(<?php echo wp_json_encode($id); ?>);if(!root)return;const form=root.querySelector('form'),btn=form.querySelector('button'),status=form.querySelector('.pd-status');const prices={month:{price:'€3,99',period:'каждый месяц'},year:{price:'€39,99',period:null}};let pending=false;const sync=()=>{const p=prices[form.elements.plan.value];root.querySelector('[data-pd-total]').textContent=p.price;root.querySelector('[data-pd-consent]').textContent=p.period?'Согласен(-на) на списание '+p.price+' сегодня и '+p.period+' до отмены.':'Согласен(-на) на разовую оплату €39,99 за 12 месяцев доступа без автоматического продления.';root.querySelector('[data-pd-note]').textContent=p.period?'Отменить продление можно в любое время. Доступ сохранится до конца оплаченного периода.':'Доступ на 12 месяцев. По окончании можно оформить новый период, автоматического списания не будет.';root.querySelector('[data-pd-button]').textContent=root.dataset.enabled==='1'?'Оформить подписку · '+p.price:'Скоро открытие';};form.addEventListener('change',e=>{if(e.target.name==='plan'){form.elements.consent.checked=false;sync()}});sync();form.addEventListener('submit',async e=>{e.preventDefault();if(root.dataset.enabled!=='1'||pending)return;pending=true;const payload={plan:form.elements.plan.value,email:form.elements.email.value.trim(),consent:form.elements.consent.checked};btn.disabled=true;form.querySelectorAll('input').forEach(x=>x.disabled=true);status.textContent='Открываем защищённую оплату…';try{const res=await fetch(root.dataset.url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await res.json();if(!res.ok||!j.ok||!j.checkout_url)throw Error(j.error||'Оплата временно недоступна.');const u=new URL(j.checkout_url);if(u.protocol!=='https:'||!/(^|\.)mollie\.com$/i.test(u.hostname))throw Error('Некорректный адрес оплаты.');location.assign(u.href)}catch(err){status.textContent=err.message;pending=false;btn.disabled=false;form.querySelectorAll('input').forEach(x=>x.disabled=false)}})})();
</script>
